<script lang="ts">
 import {onMount,onDestroy,tick} from 'svelte';
 import {dismissiblePopover} from '../primitives/dismissiblePopover';
 import WorkbenchDashboardNavigation from '../launch/WorkbenchDashboardNavigation.svelte';
 import {createWorkbenchPresence,type LocalPresenceIdentity} from './workbenchPresence';
 export let experienceId='';export let revision='';
 export let backendUrl: string;
 export let storageKey='konitif.local-declared-identity.v1';
 const presence=createWorkbenchPresence(backendUrl);
 let name='',code='',actorKind:LocalPresenceIdentity['actorKind']='human',error='',joined=false,open=false,showCode=false,dismissed='',activeTab='people',detailIdentity='';
 let menuButton:HTMLButtonElement|undefined,menuLeft=12,menuBottom=44;
 const presenceTabs=[{id:'people',label:'Personnes'},{id:'identity',label:'Identite'},{id:'collaboration',label:'Collaboration'}];
 function attachMenuButton(node:HTMLButtonElement){menuButton=node;return{destroy(){if(menuButton===node)menuButton=undefined;}};}
 function positionMenu(){if(!menuButton)return;const bounds=menuButton.getBoundingClientRect(),width=Math.min(720,window.innerWidth-24);menuLeft=Math.max(12,Math.min(bounds.right-width,window.innerWidth-width-12));menuBottom=window.innerHeight-bounds.top+8;}
 function dismissMenu(){open=false;activeTab='people';showCode=false;detailIdentity='';dismissed='all';}
 function toggleMenu(){open=!open;if(open){activeTab='people';showCode=false;detailIdentity='';positionMenu();void tick().then(()=>document.getElementById('local-presence-tab-people')?.focus());}}
 $: presence.context(experienceId,revision);
 $: menuPeople=[...$presence.people].sort((a,b)=>Number(b.self)-Number(a.self)||a.name.localeCompare(b.name));
 $: detailPerson=$presence.people.find(person=>person.identityId===detailIdentity);
 function start(){error='';try{const clean=name.trim();if(!clean||clean.length>64)throw Error('Saisir un pseudo de 1 à 64 caractères.');const association=code.trim()||Array.from(crypto.getRandomValues(new Uint8Array(24)),x=>x.toString(16).padStart(2,'0')).join('');if(!/^[a-f0-9]{48}$/.test(association))throw Error('Le code d’association doit contenir 48 caractères hexadécimaux.');const value={name:clean,code:association,actorKind};localStorage.setItem(storageKey,JSON.stringify(value));code=association;joined=true;presence.start(value);}catch(cause){error=cause instanceof Error?cause.message:String(cause);}}
 function leave(){presence.stop();joined=false;localStorage.removeItem(storageKey);code='';showCode=false;}
 onMount(()=>{try{const value=JSON.parse(localStorage.getItem(storageKey)||'null');if(value&&typeof value.name==='string'&&/^[a-f0-9]{48}$/.test(value.code)&&['human','assistant'].includes(value.actorKind)){name=value.name;code=value.code;actorKind=value.actorKind;joined=true;presence.start(value);}}catch{error='L’identité locale ne peut pas être restaurée.';}const hide=()=>presence.dispose();window.addEventListener('pagehide',hide);const resume=(event:PageTransitionEvent)=>{if(event.persisted&&joined)presence.start({name,code,actorKind});};window.addEventListener('pageshow',resume);return()=>{window.removeEventListener('pagehide',hide);window.removeEventListener('pageshow',resume);};});
 onDestroy(()=>presence.dispose());
 const initials=(value:string)=>value.trim().split(/\s+/).slice(0,2).map(part=>Array.from(part)[0]).join('').toLocaleUpperCase();
</script>
<svelte:window on:resize={positionMenu} on:keydown={event=>{if(event.key==='Escape')dismissed='all';}} />
<div class="presence" aria-label="Présence locale sur ce serveur">
 {#each $presence.people.slice(0,6) as person (person.identityId)}
  <div class="person" class:tooltipDismissed={dismissed==='all'}>
   <button on:focus={()=>dismissed=''} on:mouseenter={()=>dismissed=''} class="avatar" class:elsewhere={!person.here} aria-label={`${person.name}, ${person.actorKind==='assistant'?'assistant':'humain'}, ${person.here?'même expérience':'sur ce serveur'}`} aria-describedby={`presence-${person.identityId}`}>{initials(person.name)}</button>
   <div class="card" role="tooltip" id={`presence-${person.identityId}`}><strong>{person.name}{person.self?' · vous':''}</strong><span>{person.actorKind==='assistant'?'Assistant':'Humain'} · identité locale déclarée</span><span><b>{person.here}</b> {person.here === 1 ? "connexion dans cette expérience" : "connexions dans cette expérience"}</span><span>{person.connections} au total sur ce serveur</span>{#if person.revisions.length}<span>Révisions ici : {person.revisions.join(', ')}</span>{/if}<span>Présence uniquement · aucun suivi ni coédition</span></div>
  </div>
 {/each}
 {#if $presence.people.length>6}<span>+{$presence.people.length-6}</span>{/if}
 <button use:attachMenuButton class="manage" aria-expanded={open} aria-label="Menu utilisateur et présence locale" title={`Menu utilisateur · ${$presence.status==='connected'?'Présence connectée':$presence.status==='connecting'?'Connexion en cours':$presence.status==='error'?'Présence indisponible':'Se présenter'}`} on:click={toggleMenu}><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="7" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 9h4m-4 4h4m-4 4h4"/></svg></button>
 {#if open}<div use:dismissiblePopover={{trigger:()=>menuButton,onDismiss:dismissMenu}} class="settings" role="dialog" tabindex="-1" aria-label="Menu utilisateur" style:left={menuLeft+'px'} style:bottom={menuBottom+'px'}>
  <div class="current"><strong>{name||'Non présenté'}</strong><small>{joined?(actorKind==='assistant'?'Assistant':'Humain'):'Identité locale'} &#183; {$presence.status==='connected'?'En ligne':$presence.status==='connecting'?'Connexion...':'Hors ligne'}</small></div>
  <div class="tab-content"><WorkbenchDashboardNavigation sections={presenceTabs} bind:active={activeTab} idPrefix="local-presence" label="Menu utilisateur" let:active>
  {#if active==='people'}
   <div class="table-scroll"><table aria-label="Personnes connectees et capacites reelles"><thead><tr><th>Personne</th><th>Type</th><th>Mode</th><th>Droits partag&#233;s</th></tr></thead><tbody>
    {#each menuPeople as person (person.identityId)}<tr><td><button class="person-row" disabled={person.self} aria-label={person.self?person.name+' (vous)': 'Voir la presence de '+person.name} aria-expanded={person.self?undefined:detailIdentity===person.identityId} on:click={()=>detailIdentity=detailIdentity===person.identityId?'':person.identityId}><span class="avatar" class:elsewhere={!person.here} aria-hidden="true">{initials(person.name)}</span><span class="person-name">{person.name}<small>{person.self?'Vous · ':''}{person.here?'Même expérience':'Autre contexte'}</small></span></button></td><td>{person.actorKind==='assistant'?'Assistant':'Humain'}</td><td>Non synchronis&#233;<small>{person.connections} connexion(s) &#183; {person.here} ici</small></td><td>Non d&#233;termin&#233;s<small>Aucun r&#244;le attribu&#233;</small></td></tr>{/each}
   </tbody></table></div>
   {#if !menuPeople.length}<p>Aucune connexion observ&#233;e.</p>{/if}
   {#if detailPerson&&!detailPerson.self}<div class="person-detail" role="region" aria-label={'Presence de '+detailPerson.name}><strong>{detailPerson.name}</strong><small>{detailPerson.connections} connexion(s) sur ce serveur &#183; {detailPerson.here} ici</small>{#if detailPerson.revisions.length}<small>Versions ici : {detailPerson.revisions.join(', ')}</small>{/if}<small>Pr&#233;sence uniquement &#183; aucune permission de contenu transmise.</small></div>{/if}
  {:else if active==='identity'}
   {#if joined}<strong>{name}</strong><small>{actorKind==='assistant'?'Assistant':'Humain'}</small><button on:click={()=>showCode=!showCode}>{showCode?'Masquer':'Afficher'} le code d'association</button>{#if showCode}<label>Code priv&#233; pour associer votre autre navigateur<input readonly value={code} aria-label="Code prive d'association" /></label>{/if}<button on:click={()=>{leave();activeTab='people';}}>Quitter la pr&#233;sence</button>
   {:else}<label>Nom affich&#233;<input bind:value={name} maxlength="64" autocomplete="nickname" /></label><label>Acteur<select bind:value={actorKind}><option value="human">Humain</option><option value="assistant">Assistant</option></select></label><label>Code d'association existant (facultatif)<input type="password" bind:value={code} autocomplete="off" /></label><button on:click={()=>{start();if(joined)activeTab='people';}}>D&#233;clarer cette connexion</button>{/if}
  {:else}<table aria-label="Disponibilite des modes de collaboration"><thead><tr><th>Mode</th><th>Disponibilit&#233;</th></tr></thead><tbody><tr><td>Spectateur</td><td>Non disponible</td></tr><tr><td>&#201;dition ind&#233;pendante</td><td>Non disponible</td></tr><tr><td>Co&#233;dition synchronis&#233;e</td><td>Non disponible</td></tr></tbody></table><p>La pr&#233;sence ne partage ni actions ni disposition et n'isole pas les sauvegardes habituelles. Les droits de lecture et d'&#233;criture ne sont pas attribu&#233;s par ce menu.</p>{/if}
  </WorkbenchDashboardNavigation></div>
  {#if error||$presence.error}<p role="status">{error||$presence.error}</p>{/if}
 </div>{/if}
</div>
<style>
 .presence{position:relative;display:flex;align-items:center;gap:4px;font-size:11px;color:var(--color-text-primary);margin-right:8px}.person{position:relative}.avatar{border-radius:50%;width:26px;height:26px;display:grid;place-items:center;border:1px solid var(--color-border-subtle);background:var(--color-background-muted);color:inherit;font:600 10px system-ui;cursor:default}.elsewhere{opacity:.5}.card,.settings{position:absolute;bottom:calc(100% + 8px);right:0;width:310px;padding:12px;box-sizing:border-box;border:1px solid var(--color-border-subtle);border-radius:8px;background:var(--color-background-muted);box-shadow:0 8px 32px #0003;z-index:1000;line-height:1.5}.card{display:none;pointer-events:none}.card span{display:block;margin-top:5px}.person:not(.tooltipDismissed):hover .card,.person:not(.tooltipDismissed):focus-within .card{display:block}.manage,button,input,select{font:inherit;color:inherit}.manage{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;flex:none;background:transparent;border:1px solid var(--color-border-subtle);border-radius:5px;padding:0;cursor:pointer}.settings{position:fixed;right:auto;width:min(720px,calc(100vw - 24px));height:min(430px,calc(100vh - 80px));max-height:80vh;overflow:auto;display:flex;flex-direction:column}.tab-content{flex:1;min-height:0;margin-top:10px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:11px}th,td{padding:7px 4px;border-bottom:1px solid var(--color-border-subtle);vertical-align:top}th{color:var(--color-text-secondary);font-weight:500}td:first-child{min-width:130px}td{min-width:70px}.settings label{display:block;margin:8px 0}.settings input:not([type=radio]),select{display:block;width:100%;box-sizing:border-box;background:var(--color-background-muted);border:1px solid var(--color-border-subtle);padding:6px;border-radius:4px}.settings button{padding:5px;margin:4px 3px 4px 0;background:var(--color-background-muted);border:1px solid var(--color-border-subtle);border-radius:4px;cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--color-accent-primary,#6a9fe8);outline-offset:2px}p{margin:7px 0;color:var(--color-text-secondary)}

 .current{padding:4px 4px 12px;border-bottom:1px solid var(--color-border-subtle)}small{display:block;color:var(--color-text-secondary);font-size:10px;line-height:1.5}.settings .person-row{width:100%;display:flex;align-items:center;gap:9px;text-align:left;background:transparent;border:0;margin:0;padding:8px;border-radius:5px}.settings .person-row:disabled{opacity:1;cursor:default}.person-row:not(:disabled):hover{background:var(--color-background-panel)}.person-name{min-width:0;overflow-wrap:anywhere;flex:1;font-size:12px}.person-row .avatar{flex:none}.person-detail{margin:5px 0;padding:9px;background:var(--color-background-panel);border-radius:5px}
</style>
